<?phpheader("Access-Control-Allow-Origin: *");require_once "config.php";require_once "jwt.php";$headers = getallheaders();$tokendata = $headers["X-Authorization"] ?? "";if ($_SERVER["REQUEST_METHOD"] === "POST") {	if ($tokendata) {		$token_array = explode(" ", $tokendata);		if ($token_array[0] == "Bearer") {			$token = $token_array[1];			$decodedToken = verifyToken($token, JWT_SECRET_KEY, $conn);			if ($decodedToken) {				$_REQUEST = json_decode(file_get_contents("php://input"), true);				$arrResults = array();				 $user_id = $_REQUEST["user_id"];				if ($user_id != "") {					$Usersql = "SELECT survey.id, survey.survey_name,survey.unique_id, survey.created_at FROM survey where survey.status = 1 and survey.del_action='N' and survey.id in(SELECT DISTINCT(survey_id) FROM assign_survey WHERE status='0' AND user_id='" . $user_id . "') ORDER BY survey.survey_name ASC ";					$return_arr = array();					mysqli_set_charset($conn, 'utf8');					$fetch = mysqli_query($conn, $Usersql);					$rows = array();					while ($row = mysqli_fetch_array($fetch, MYSQLI_ASSOC)) {						$row["survey_name"] = $row["survey_name"];						$rows[] = $row;					}					echo json_encode($rows);				} else {					$rows = array("status" => 0, "message" => "User Id Are Required.");					echo json_encode($rows);				}				exit;			}		} else {			$response = ["status" => 0, "message" => "Auth request is invalid"];			echo json_encode($response);			exit;		}	}	http_response_code(401); // Unauthorized status code	$response = ["status" => 0, "error" => "Invalid token"];	echo json_encode($response);	exit;} else {	http_response_code(405); // Method Not Allowed	$response = ["status"=>0, "message" => "The call method not allowed"];	echo json_encode($response);	exit;	}